CREATE OR REPLACE VIEW GATEC_AGR.GAV_ACUM_D4_DIA AS
select  d4.cod_empr,  d4.saf_ano_safra,  d4.cod_divi1,  d4.cod_divi2,  d4.cod_divi3,  d4.cod_divi4,  lib.id_liber,  nvl(din_tipo_corte_1,1) cod_tip_corte,  cont_dia_balanca  ac_dt_acum,  d4.id_divi4,  sum( gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ) ) ac_prod,  sum( decode(             nvl(pan_brix,0),0,0,decode(                                         nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                       )            )    ) ac_prod_anali,  sum( decode(              nvl(pan_brix,0),0,0,decode(                                       nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 )*pan_brix,0                                        )             )     )/  decode( sum( decode(               nvl(pan_brix,0),0,0,decode(                                           nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                         )            )          ),0,1,          sum( decode(              nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                         )             )         )       ) ac_pond_brix,  sum( decode(              nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 )*pan_ls,0                                          )            )    )/  decode( sum( decode(              nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                        )            )         ),0,1,         sum( decode(               nvl(pan_brix,0),0,0,decode(                                           nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                        )            )         )       ) ac_pond_ls,  sum( decode(              nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 )*pan_pbu,0                                        )            )    )/  decode( sum( decode(              nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                        )            )         ),0,1,         sum( decode(              nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                        )            )         )       ) ac_pond_pbu, Sum (gaf_peso_liqui(cont_peso_liqui, vc.id_liber, d4.id_divi4, 0, 0) * cont_tempo_queim)    /  decode( sum(gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 )),0,1,         sum(gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ) ) ) ac_pond_temp_quei,  sum( decode(              nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 )*pan_ar,0                                        )            )    )/  decode( sum( decode(               nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                        )            )         ),0,1,         sum( decode(              nvl(pan_brix,0),0,0,decode(                                          nvl(cod_mot_can,0),0,gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ),0                                        )            )         )       ) ac_pond_ar,  Sum (gaf_peso_liqui(cont_peso_liqui, vc.id_liber, d4.id_divi4, 0, 0) * cont_tempo_corte)    / decode( sum(gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 )),0,1,         sum(gaf_peso_liqui( cont_peso_liqui,vc.id_liber,d4.id_divi4,0,0 ) ) ) ac_pond_temp_corte, ' ' ac_debcre  from ga_var_container vc,    ga_anali_sonda aso,    ga_divi4 d4,    ga_liberacao lib,    ga_area_liber lib4  where vc.id_liber = lib4.id_liber and     lib.id_liber = lib4.id_liber and     d4.id_divi4 = lib4.id_divi4 and     aso.id_lanc_conta (+) = vc.id_lanc_conta     and cont_dia_balanca >= to_date('07/02/2003','dd/mm/yyyy')  Group By   cont_dia_balanca,   d4.cod_empr,   d4.saf_ano_safra,   d4.cod_divi1,   d4.cod_divi2,   d4.cod_divi3,   d4.cod_divi4,   lib.id_liber,   din_tipo_corte_1,   lib.cod_finalid,   d4.id_divi4 
 
 
/
